package application.model.dao;
import application.model.connection.DatabaseConnection; import application.model.entity.*; import java.sql.*; import java.util.*;
public class InsumoDAO {
 public List<Insumo> activos(){List<Insumo>a=new ArrayList<>();String q="SELECT id_insumo,nombre,unidad_base,costo_cent_x1000 FROM insumos WHERE activo=1 ORDER BY nombre";try(Connection c=DatabaseConnection.getConnection();Statement s=c.createStatement();ResultSet r=s.executeQuery(q)){while(r.next())a.add(new Insumo(r.getInt(1),r.getString(2),r.getString(3),r.getInt(4)));return a;}catch(SQLException e){throw new IllegalStateException("No se pudieron leer los insumos",e);}}
 public List<InsumoAdmin> todos(){List<InsumoAdmin>a=new ArrayList<>();String q="SELECT i.id_insumo,i.nombre,i.unidad_base,i.stock,i.stock_minimo,i.costo_cent_x1000,i.id_proveedor,COALESCE(p.nombre,''),i.activo,(SELECT COUNT(DISTINCT r.id_producto) FROM recetas r WHERE r.id_insumo=i.id_insumo) FROM insumos i LEFT JOIN proveedores p USING(id_proveedor) ORDER BY i.nombre";try(Connection c=DatabaseConnection.getConnection();Statement s=c.createStatement();ResultSet r=s.executeQuery(q)){while(r.next()){int pid=r.getInt(7);Integer prov=r.wasNull()?null:pid;a.add(new InsumoAdmin(r.getInt(1),r.getString(2),r.getString(3),r.getInt(4),r.getInt(5),r.getInt(6),prov,r.getString(8),r.getInt(9)==1,r.getInt(10)));}return a;}catch(SQLException e){throw new IllegalStateException("No se pudieron leer los insumos",e);}}
 public List<Proveedor> proveedores(){List<Proveedor>a=new ArrayList<>();String q="SELECT p.id_proveedor,p.nombre,COALESCE(p.telefono,''),COALESCE(p.rtn,''),p.activo,(SELECT COUNT(*) FROM insumos i WHERE i.id_proveedor=p.id_proveedor) FROM proveedores p ORDER BY p.nombre";try(Connection c=DatabaseConnection.getConnection();Statement s=c.createStatement();ResultSet r=s.executeQuery(q)){while(r.next())a.add(new Proveedor(r.getInt(1),r.getString(2),r.getString(3),r.getString(4),r.getInt(5)==1,r.getInt(6)));return a;}catch(SQLException e){throw new IllegalStateException("No se pudieron leer los proveedores",e);}}
 public void guardar(Integer id,String n,String u,int min,int costo,Integer prov,boolean activo){if(id!=null){try(Connection c=DatabaseConnection.getConnection();PreparedStatement p=c.prepareStatement("SELECT unidad_base,stock,(SELECT COUNT(*) FROM recetas WHERE id_insumo=?) FROM insumos WHERE id_insumo=?")){p.setInt(1,id);p.setInt(2,id);try(ResultSet r=p.executeQuery()){if(!r.next())throw new IllegalStateException("El insumo ya no existe");if(!r.getString(1).equals(u)&&(r.getInt(2)!=0||r.getInt(3)>0))throw new IllegalStateException("No se puede cambiar la unidad de un insumo con stock o recetas");}}catch(SQLException e){throw new IllegalStateException("No se pudo validar la unidad del insumo",e);}}int x=u.equals("ud")?Math.multiplyExact(costo,1000):costo;String q=id==null?"INSERT INTO insumos(nombre,unidad_base,stock_minimo,costo_cent_x1000,id_proveedor,activo) VALUES(?,?,?,?,?,?)":"UPDATE insumos SET nombre=?,unidad_base=?,stock_minimo=?,costo_cent_x1000=?,id_proveedor=?,activo=? WHERE id_insumo=?";try(Connection c=DatabaseConnection.getConnection();PreparedStatement p=c.prepareStatement(q)){p.setString(1,n);p.setString(2,u);p.setInt(3,min);p.setInt(4,x);if(prov==null)p.setNull(5,Types.INTEGER);else p.setInt(5,prov);p.setInt(6,activo?1:0);if(id!=null)p.setInt(7,id);if(p.executeUpdate()!=1)throw new IllegalStateException("El insumo ya no existe");}catch(SQLException e){if(e.getMessage()!=null&&e.getMessage().contains("UNIQUE"))throw new IllegalStateException("Ya existe un insumo con ese nombre");throw new IllegalStateException("No se pudo guardar el insumo",e);}}
 public void proveedor(Integer id,String n,String tel,String rtn,boolean a){String q=id==null?"INSERT INTO proveedores(nombre,telefono,rtn,activo) VALUES(?,?,?,?)":"UPDATE proveedores SET nombre=?,telefono=?,rtn=?,activo=? WHERE id_proveedor=?";try(Connection c=DatabaseConnection.getConnection();PreparedStatement p=c.prepareStatement(q)){p.setString(1,n);p.setString(2,tel);p.setString(3,rtn);p.setInt(4,a?1:0);if(id!=null)p.setInt(5,id);if(p.executeUpdate()!=1)throw new IllegalStateException("El proveedor ya no existe");}catch(SQLException e){if(e.getMessage()!=null&&e.getMessage().contains("UNIQUE"))throw new IllegalStateException("Ya existe un proveedor con ese nombre");throw new IllegalStateException("No se pudo guardar el proveedor",e);}}
 public void compra(int id,int qty,int total,boolean update,String nota){if(qty<=0||total<=0)throw new IllegalArgumentException("La cantidad y el costo deben ser mayores que cero");try(Connection c=DatabaseConnection.getConnection()){c.setAutoCommit(false);try(PreparedStatement p=c.prepareStatement("UPDATE insumos SET stock=stock+?,costo_cent_x1000=CASE WHEN ?=1 THEN ? ELSE costo_cent_x1000 END WHERE id_insumo=?")){p.setInt(1,qty);p.setInt(2,update?1:0);p.setInt(3,(int)Math.round(total*1000.0/qty));p.setInt(4,id);if(p.executeUpdate()!=1)throw new IllegalStateException("El insumo ya no existe");}mov(c,id,"Compra",qty,nota);c.commit();}catch(SQLException e){throw new IllegalStateException("No se pudo registrar la compra",e);}}
 public void ajuste(int id,int delta,String nota){if(delta==0)throw new IllegalArgumentException("El ajuste no puede ser cero");try(Connection c=DatabaseConnection.getConnection()){c.setAutoCommit(false);try(PreparedStatement p=c.prepareStatement("UPDATE insumos SET stock=stock+? WHERE id_insumo=?")){p.setInt(1,delta);p.setInt(2,id);if(p.executeUpdate()!=1)throw new IllegalStateException("El insumo ya no existe");}mov(c,id,"Ajuste",delta,nota);c.commit();}catch(SQLException e){throw new IllegalStateException("No se pudo ajustar el stock",e);}}
 private void mov(Connection c,int id,String tipo,int qty,String nota)throws SQLException{try(PreparedStatement p=c.prepareStatement("INSERT INTO movimientos_inventario(id_insumo,tipo,cantidad,nota) VALUES(?,?,?,?)")){p.setInt(1,id);p.setString(2,tipo);p.setInt(3,qty);p.setString(4,nota);p.executeUpdate();}}
 public static void consumir(Connection c,int venta)throws SQLException{String q="SELECT r.id_insumo,SUM(r.cantidad*d.cantidad) FROM detalle_ventas d JOIN recetas r ON r.id_producto=d.id_producto WHERE d.id_venta=? GROUP BY r.id_insumo";try(PreparedStatement p=c.prepareStatement(q)){p.setInt(1,venta);try(ResultSet r=p.executeQuery()){while(r.next()){int id=r.getInt(1),n=r.getInt(2);try(PreparedStatement u=c.prepareStatement("UPDATE insumos SET stock=stock-? WHERE id_insumo=?")){u.setInt(1,n);u.setInt(2,id);u.executeUpdate();}try(PreparedStatement m=c.prepareStatement("INSERT INTO movimientos_inventario(id_insumo,tipo,cantidad,id_venta,nota) VALUES(?,'Venta',?,?,'Consumo de receta')")){m.setInt(1,id);m.setInt(2,-n);m.setInt(3,venta);m.executeUpdate();}}}}}
 public List<MovimientoInventario> historial(int id){List<MovimientoInventario>a=new ArrayList<>();String q="SELECT creado_en,tipo,cantidad,unidad_base,COALESCE(nota,'') FROM movimientos_inventario m JOIN insumos i USING(id_insumo) WHERE m.id_insumo=? ORDER BY id_movimiento DESC LIMIT 100";try(Connection c=DatabaseConnection.getConnection();PreparedStatement p=c.prepareStatement(q)){p.setInt(1,id);try(ResultSet r=p.executeQuery()){while(r.next())a.add(new MovimientoInventario(r.getString(1),r.getString(2),r.getInt(3),r.getString(4),r.getString(5)));}return a;}catch(SQLException e){throw new IllegalStateException("No se pudo leer el historial del insumo",e);}}
}
